"use client";

import {
  Activity, AlertTriangle, BellRing, Boxes, CalendarClock, Check, ChevronRight, ClipboardPlus,
  FileHeart, FileText, History, LayoutDashboard, Loader2, Menu, PackagePlus, PackageSearch,
  Plus, Printer, Search, ShieldCheck, SlidersHorizontal, Stethoscope, Syringe, UserPlus, UsersRound, X,
} from "lucide-react";
import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { Toaster } from "@/components/ui/sonner";

type Section = "dashboard" | "patients" | "prescriptions" | "applications" | "stock" | "reminders" | "admin";
type User = { id: number; nome: string; email: string; papel: "medico_admin" | "recepcao" };
type Patient = { id: number; nome: string; nascimento: string; cpf: string | null; telefone: string; endereco: string; contatoEmergencia: string; observacoesAdmin: string };
type Product = { id: number; nome: string; principioAtivo: string; apresentacao: string; unidade: string; estoqueMinimo: number };
type Lot = { id: number; produtoId: number; numero: string; validade: string; recebidoEm: string; saldo: number };
type Reminder = { id: number; pacienteId: number; pacienteNome: string; telefone: string; produtoId: number | null; produtoNome: string | null; dataPrevista: string; estado: string; notaAdministrativa: string };
type Prescription = { id: number; pacienteId: number; pacienteNome: string; medicoNome: string; estado: string; criadoEm: string; finalizadoEm: string | null; itemId: number; produtoId: number; produtoNome: string; apresentacao: string; concentracao: string; dose: string; via: string; quantidade: number; instrucoes: string; recorrenciaDias: number | null; observacoes: string };
type Application = { id: number; prescricaoId: number; pacienteId: number; pacienteNome: string; produtoNome: string; loteNumero: string; quantidade: number; localAplicacao: string; observacoes: string; reacao: string; aplicadoEm: string; estornadaEm: string | null };
type Symptom = { id: number; nome: string };
type Assessment = { id: number; pacienteId: number; sintomaId: number; sintomaNome: string; intensidade: number; observacao: string; avaliadoEm: string };
type Chart = { id: number; pacienteId: number; anamnese: string; alergias: string; condicoes: string; medicamentos: string; atualizadoEm: string };
type Evolution = { id: number; pacienteId: number; autorNome: string; texto: string; tipo: string; evolucaoOriginalId: number | null; criadoEm: string };
type AuditRow = { id: number; usuarioNome: string | null; acao: string; entidade: string; entidadeId: string; detalhes: string; criadoEm: string };
type UserRow = { id: number; nome: string; email: string; papel: "medico_admin" | "recepcao"; ativo: boolean };
type Payload = { user: User; patients: Patient[]; products: Product[]; lots: Lot[]; reminders: Reminder[]; prescriptions: Prescription[]; applications: Application[]; symptoms: Symptom[]; assessments: Assessment[]; charts: Chart[]; evolutions: Evolution[]; audit: AuditRow[]; users: UserRow[]; settings: { expiryAlertDays: number } };

const navItems: { id: Section; label: string; icon: typeof LayoutDashboard }[] = [
  { id: "dashboard", label: "Visão geral", icon: LayoutDashboard }, { id: "patients", label: "Pacientes", icon: UsersRound },
  { id: "prescriptions", label: "Prescrições", icon: FileText }, { id: "applications", label: "Aplicações", icon: Syringe },
  { id: "stock", label: "Estoque", icon: Boxes }, { id: "reminders", label: "Recorrências", icon: CalendarClock },
  { id: "admin", label: "Administração", icon: SlidersHorizontal },
];

const emptyData: Payload = { user: { id: 0, nome: "", email: "", papel: "medico_admin" }, patients: [], products: [], lots: [], reminders: [], prescriptions: [], applications: [], symptoms: [], assessments: [], charts: [], evolutions: [], audit: [], users: [], settings: { expiryAlertDays: 60 } };
const fmtDate = (value?: string | null) => value ? new Intl.DateTimeFormat("pt-BR", { timeZone: "America/Fortaleza", day: "2-digit", month: "short", year: "numeric" }).format(new Date(value.includes("T") ? value : `${value}T12:00:00-03:00`)) : "—";
const fmtDateTime = (value: string) => new Intl.DateTimeFormat("pt-BR", { timeZone: "America/Fortaleza", dateStyle: "short", timeStyle: "short" }).format(new Date(value));
const initials = (name: string) => name.split(" ").filter(Boolean).slice(0, 2).map((n) => n[0]).join("").toUpperCase();
const today = () => new Date().toLocaleDateString("en-CA", { timeZone: "America/Fortaleza" });

async function postAction(body: Record<string, unknown>) {
  const response = await fetch("/api/cti", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  const result = await response.json() as { error?: string; [key: string]: unknown };
  if (!response.ok) throw new Error(result.error || "Não foi possível concluir a operação.");
  return result;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return <div className="space-y-2"><Label className="text-sm font-semibold text-slate-700">{label}</Label>{children}</div>;
}

function Empty({ icon: Icon, title, text, action }: { icon: typeof Search; title: string; text: string; action?: React.ReactNode }) {
  return <div className="grid min-h-56 place-items-center p-8 text-center"><div><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-blue-50 text-[#0b4ea2]"><Icon className="h-6 w-6" /></span><h3 className="mt-4 font-bold">{title}</h3><p className="mx-auto mt-1 max-w-sm text-sm leading-6 text-slate-500">{text}</p>{action && <div className="mt-5">{action}</div>}</div></div>;
}

export function CtiApp({ signedInName }: { signedInName: string }) {
  const [data, setData] = useState<Payload>(emptyData);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [section, setSection] = useState<Section>("dashboard");
  const [mobileNav, setMobileNav] = useState(false);
  const [search, setSearch] = useState("");
  const [patientDialog, setPatientDialog] = useState(false);
  const [stockDialog, setStockDialog] = useState(false);
  const [rxDialog, setRxDialog] = useState(false);
  const [applicationRx, setApplicationRx] = useState<Prescription | null>(null);
  const [selectedPatientId, setSelectedPatientId] = useState<number | null>(null);
  const [printRx, setPrintRx] = useState<Prescription | null>(null);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    try { setError(""); const response = await fetch("/api/cti", { cache: "no-store" }); const payload = await response.json() as Payload & { error?: string }; if (!response.ok) throw new Error(payload.error); setData(payload); }
    catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar o sistema."); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { void load(); }, [load]);

  const run = async (action: Record<string, unknown>, success: string, close?: () => void) => {
    setSaving(true); try { await postAction(action); toast.success(success); close?.(); await load(); }
    catch (err) { toast.error(err instanceof Error ? err.message : "Falha ao salvar."); } finally { setSaving(false); }
  };

  useEffect(() => {
    const context = (document as Document & { modelContext?: { registerTool: (tool: unknown, options?: { signal?: AbortSignal }) => void | Promise<void> } }).modelContext;
    if (!context?.registerTool) return;
    const lifecycle = new AbortController();
    void Promise.resolve(context.registerTool({ name: "cti_abrir_area", title: "Abrir área da CTI", description: "Navega para uma área operacional visível do sistema CTI.", inputSchema: { type: "object", properties: { area: { type: "string", enum: navItems.map((n) => n.id) } }, required: ["area"], additionalProperties: false }, annotations: { readOnlyHint: true, untrustedContentHint: false }, execute(input: { area: Section }) { if (!navItems.some((item) => item.id === input?.area)) throw new Error("Área inválida."); setSection(input.area); return { area: input.area, aberto: true }; } }, { signal: lifecycle.signal })).catch(() => undefined);
    void Promise.resolve(context.registerTool({ name: "cti_resumo_operacional", title: "Consultar resumo operacional", description: "Retorna contagens do painel da clínica sem expor conteúdo clínico.", inputSchema: { type: "object", properties: {}, additionalProperties: false }, annotations: { readOnlyHint: true, untrustedContentHint: false }, execute() { return { pacientes: data.patients.length, prescricoesPendentes: data.prescriptions.filter((r) => r.estado === "finalizada").length, retornosAbertos: data.reminders.filter((r) => !["concluido", "cancelado"].includes(r.estado)).length, produtosComEstoqueBaixo: lowStock.length }; } }, { signal: lifecycle.signal })).catch(() => undefined);
    return () => lifecycle.abort();
  }, [data]);

  const filteredPatients = data.patients.filter((p) => `${p.nome} ${p.cpf ?? ""} ${p.telefone}`.toLowerCase().includes(search.toLowerCase()));
  const selectedPatient = data.patients.find((p) => p.id === selectedPatientId) ?? null;
  const stockByProduct = data.products.map((p) => ({ ...p, balance: data.lots.filter((l) => l.produtoId === p.id).reduce((sum, l) => sum + l.saldo, 0) }));
  const lowStock = stockByProduct.filter((p) => p.balance <= p.estoqueMinimo);
  const expiring = data.lots.filter((l) => l.saldo > 0 && l.validade <= new Date(Date.now() + data.settings.expiryAlertDays * 86400000).toISOString().slice(0, 10));
  const openReminders = data.reminders.filter((r) => !["concluido", "cancelado"].includes(r.estado));
  const pendingRx = data.prescriptions.filter((r) => r.estado === "finalizada" || r.estado === "parcialmente_aplicada");
  const isDoctor = data.user.papel === "medico_admin";
  const userName = data.user.nome || signedInName;

  const openSection = (id: Section) => { setSection(id); setMobileNav(false); setSelectedPatientId(null); };
  const pageTitle = navItems.find((n) => n.id === section)?.label ?? "Visão geral";

  if (loading) return <div className="grid min-h-screen place-items-center bg-[#f4f7fb]"><div className="text-center"><Loader2 className="mx-auto h-8 w-8 animate-spin text-[#0b4ea2]" /><p className="mt-3 text-sm text-slate-500">Abrindo o ambiente protegido…</p></div></div>;

  if (error) return <div className="grid min-h-screen place-items-center bg-[#f4f7fb] p-6"><div className="max-w-md rounded-2xl border border-rose-200 bg-white p-7 text-center shadow-xl"><AlertTriangle className="mx-auto h-8 w-8 text-rose-500" /><h1 className="mt-4 text-xl font-bold">O sistema não pôde ser carregado</h1><p className="mt-2 text-sm leading-6 text-slate-500">{error}</p><Button className="mt-5" onClick={() => { setLoading(true); void load(); }}>Tentar novamente</Button></div></div>;

  return <main className="min-h-screen bg-[#f4f7fb] text-[#10203b]">
    <aside className={`fixed inset-y-0 left-0 z-40 w-[264px] border-r border-white/10 bg-[#071f4d] text-white transition-transform lg:translate-x-0 print:hidden ${mobileNav ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-[92px] items-center gap-3 border-b border-white/10 px-6"><img src="/logo.jpg" alt="CTI Centro de Terapias Integradas" className="h-12 w-12 rounded-xl bg-white object-contain p-1" /><div><strong className="block text-xl tracking-[.08em]">CTI</strong><span className="text-xs text-blue-200">Gestão clínica</span></div></div>
      <nav aria-label="Navegação principal" className="space-y-1.5 p-4">{navItems.filter((item) => item.id !== "admin" || isDoctor).map(({ id, label, icon: Icon }) => <button key={id} onClick={() => openSection(id)} className={`flex w-full items-center gap-3 rounded-xl px-4 py-3 text-left text-[15px] font-medium transition ${section === id ? "bg-white text-[#0a2b67] shadow-lg shadow-blue-950/20" : "text-blue-100 hover:bg-white/10 hover:text-white"}`}><Icon className="h-[19px] w-[19px]" />{label}</button>)}</nav>
      <div className="absolute inset-x-4 bottom-5 rounded-2xl border border-cyan-300/20 bg-cyan-300/10 p-4"><div className="flex items-center gap-2 text-sm font-semibold"><ShieldCheck className="h-4 w-4 text-cyan-300" /> Ambiente protegido</div><p className="mt-2 text-xs leading-5 text-blue-100">Dados clínicos com acesso restrito e rastreável.</p></div>
    </aside>
    {mobileNav && <button aria-label="Fechar menu" className="fixed inset-0 z-30 bg-slate-950/40 lg:hidden" onClick={() => setMobileNav(false)} />}

    <section className="min-h-screen lg:pl-[264px] print:pl-0">
      <header className="sticky top-0 z-20 flex h-[76px] items-center gap-4 border-b border-slate-200/80 bg-white/90 px-4 backdrop-blur-xl sm:px-7 lg:px-10 print:hidden"><button aria-label="Abrir menu" onClick={() => setMobileNav(true)} className="rounded-xl border border-slate-200 p-2.5 lg:hidden"><Menu className="h-5 w-5" /></button><div className="relative hidden max-w-md flex-1 sm:block"><Search className="absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><input value={search} onChange={(e) => setSearch(e.target.value)} onFocus={() => setSection("patients")} aria-label="Buscar pacientes" placeholder="Buscar paciente por nome, CPF ou telefone" className="h-11 w-full rounded-xl border border-slate-200 bg-slate-50 pl-10 pr-4 text-sm outline-none transition focus:border-blue-400 focus:ring-4 focus:ring-blue-100" /></div><div className="ml-auto flex items-center gap-3"><button onClick={() => setSection("reminders")} aria-label="Notificações" className="relative rounded-xl border border-slate-200 p-2.5 text-slate-600"><BellRing className="h-5 w-5" />{openReminders.length > 0 && <span className="absolute -right-1 -top-1 min-w-4 rounded-full border-2 border-white bg-rose-500 px-1 text-[9px] font-bold text-white">{openReminders.length}</span>}</button><div className="hidden text-right sm:block"><strong className="block text-sm">{userName}</strong><span className="text-xs text-slate-500">{isDoctor ? "Médico administrador" : "Recepção"}</span></div><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#0b4ea2] text-sm font-bold text-white">{initials(userName)}</span></div></header>

      <div className="mx-auto max-w-[1500px] p-4 sm:p-7 lg:p-10 print:hidden">
        {section === "dashboard" && <Dashboard data={data} userName={userName} isDoctor={isDoctor} lowStock={lowStock.length} expiring={expiring.length} pendingRx={pendingRx.length} onSection={openSection} onNewPatient={() => setPatientDialog(true)} onNewRx={() => setRxDialog(true)} />}
        {section === "patients" && !selectedPatient && <Patients patients={filteredPatients} search={search} setSearch={setSearch} onNew={() => setPatientDialog(true)} onOpen={(id) => setSelectedPatientId(id)} />}
        {section === "patients" && selectedPatient && <PatientDetail patient={selectedPatient} data={data} isDoctor={isDoctor} onBack={() => setSelectedPatientId(null)} onRun={run} saving={saving} onNewRx={() => setRxDialog(true)} />}
        {section === "prescriptions" && <Prescriptions rows={data.prescriptions} isDoctor={isDoctor} onNew={() => setRxDialog(true)} onPrint={(rx) => { setPrintRx(rx); setTimeout(() => window.print(), 120); }} />}
        {section === "applications" && <Applications pending={pendingRx} applied={data.applications} lots={data.lots} products={data.products} isDoctor={isDoctor} onApply={setApplicationRx} />}
        {section === "stock" && <Stock products={stockByProduct} lots={data.lots} onReceive={() => setStockDialog(true)} />}
        {section === "reminders" && <Reminders rows={data.reminders} onRun={run} saving={saving} />}
        {section === "admin" && <Admin data={data} isDoctor={isDoctor} onRun={run} saving={saving} />}
      </div>
    </section>

    <PatientDialog open={patientDialog} setOpen={setPatientDialog} run={run} saving={saving} />
    <StockDialog open={stockDialog} setOpen={setStockDialog} products={data.products} run={run} saving={saving} />
    <PrescriptionDialog open={rxDialog} setOpen={setRxDialog} patients={data.patients} products={data.products} run={run} saving={saving} />
    <ApplicationDialog rx={applicationRx} setRx={setApplicationRx} lots={data.lots} run={run} saving={saving} />
    {printRx && <PrescriptionPrint rx={printRx} onClose={() => setPrintRx(null)} />}
    <Toaster position="top-right" richColors />
  </main>;
}

function Dashboard({ data, userName, isDoctor, lowStock, expiring, pendingRx, onSection, onNewPatient, onNewRx }: { data: Payload; userName: string; isDoctor: boolean; lowStock: number; expiring: number; pendingRx: number; onSection: (s: Section) => void; onNewPatient: () => void; onNewRx: () => void }) {
  const first = userName.split(" ")[0];
  const open = data.reminders.filter((r) => !["concluido", "cancelado"].includes(r.estado));
  const overdue = open.filter((r) => r.dataPrevista < today());
  const cards = [
    { title: `${overdue.length} retorno${overdue.length === 1 ? "" : "s"} vencido${overdue.length === 1 ? "" : "s"}`, detail: "Precisam de contato", tone: "rose", icon: BellRing, section: "reminders" as Section },
    { title: `${expiring} lote${expiring === 1 ? "" : "s"} a vencer`, detail: "Nos próximos 60 dias", tone: "amber", icon: AlertTriangle, section: "stock" as Section },
    { title: `${lowStock} produto${lowStock === 1 ? "" : "s"} com estoque baixo`, detail: "Saldo no mínimo ou abaixo", tone: "blue", icon: PackageSearch, section: "stock" as Section },
  ];
  return <><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-1 text-sm font-semibold text-[#0b74c9]">{new Intl.DateTimeFormat("pt-BR", { dateStyle: "full", timeZone: "America/Fortaleza" }).format(new Date())}</p><h1 className="text-2xl font-bold tracking-tight sm:text-3xl">Olá, {first}</h1><p className="mt-1 text-slate-500">Veja o que precisa de atenção na CTI.</p></div><div className="flex gap-2"><Button variant="outline" onClick={onNewPatient}><UserPlus />Novo paciente</Button>{isDoctor && <Button onClick={onNewRx}><ClipboardPlus />Nova prescrição</Button>}</div></div>
    <div className="mt-8 grid gap-4 md:grid-cols-3">{cards.map(({ title, detail, tone, icon: Icon, section }) => <button key={title} onClick={() => onSection(section)} className="rounded-2xl border border-slate-200/80 bg-white p-5 text-left shadow-[0_8px_28px_rgba(15,42,86,.05)] transition hover:-translate-y-0.5 hover:shadow-lg"><div className="flex items-start gap-4"><span className={`grid h-11 w-11 shrink-0 place-items-center rounded-xl tone-${tone}`}><Icon className="h-5 w-5" /></span><div><h2 className="font-bold">{title}</h2><p className="mt-1 text-sm text-slate-500">{detail}</p></div><ChevronRight className="ml-auto mt-2 h-4 w-4 text-slate-400" /></div></button>)}</div>
    <div className="mt-7 grid gap-6 xl:grid-cols-[1.45fr_.8fr]"><article className="overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-[0_8px_28px_rgba(15,42,86,.05)]"><div className="flex items-center justify-between border-b border-slate-100 p-5 sm:p-6"><div><h2 className="text-lg font-bold">Retornos prioritários</h2><p className="mt-1 text-sm text-slate-500">Contatos programados após aplicações</p></div><button onClick={() => onSection("reminders")} className="text-sm font-semibold text-[#0b62b5]">Ver todos</button></div>{open.length ? <div className="divide-y divide-slate-100">{open.slice(0, 4).map((item) => <button onClick={() => onSection("reminders")} key={item.id} className="flex w-full flex-wrap items-center gap-3 p-4 text-left hover:bg-slate-50 sm:flex-nowrap sm:px-6"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-blue-50 text-sm font-bold text-[#0b4ea2]">{initials(item.pacienteNome)}</span><div className="min-w-[160px] flex-1"><strong className="block text-sm">{item.pacienteNome}</strong><span className="text-xs text-slate-500">{item.telefone}</span></div><div className="min-w-[135px]"><span className="block text-xs text-slate-400">Recorrência</span><strong className="text-sm font-medium">{item.produtoNome ?? "Retorno"}</strong></div><div className="min-w-[100px]"><span className="block text-xs text-slate-400">Data</span><strong className="text-sm font-medium">{fmtDate(item.dataPrevista)}</strong></div><Status status={item.dataPrevista < today() ? "vencido" : item.estado} /></button>)}</div> : <Empty icon={BellRing} title="Nenhum retorno pendente" text="Os próximos retornos aparecerão aqui depois das aplicações recorrentes." />}</article>
      <aside className="rounded-2xl bg-gradient-to-br from-[#0a2e6d] to-[#087ab4] p-6 text-white shadow-xl shadow-blue-950/15"><div className="flex items-center justify-between"><span className="grid h-11 w-11 place-items-center rounded-xl bg-white/12"><Activity className="h-5 w-5 text-cyan-200" /></span><span className="rounded-full bg-emerald-300/20 px-3 py-1 text-xs font-semibold text-emerald-100">Dados atuais</span></div><h2 className="mt-7 text-lg font-bold">Movimento clínico</h2><p className="mt-1 text-sm text-blue-100">Visão consolidada do sistema</p><div className="mt-6 grid grid-cols-2 gap-3"><div className="rounded-xl bg-white/10 p-4"><strong className="block text-3xl">{data.applications.length}</strong><span className="text-xs text-blue-100">Aplicações</span></div><div className="rounded-xl bg-white/10 p-4"><strong className="block text-3xl">{data.patients.length}</strong><span className="text-xs text-blue-100">Pacientes</span></div><div className="col-span-2 rounded-xl bg-white/10 p-4"><strong className="block text-2xl">{pendingRx}</strong><span className="text-xs text-blue-100">Prescrições aguardando aplicação</span></div></div></aside></div></>;
}

function PageHeading({ eyebrow, title, text, action }: { eyebrow: string; title: string; text: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-1 text-sm font-semibold text-[#0b74c9]">{eyebrow}</p><h1 className="text-2xl font-bold tracking-tight sm:text-3xl">{title}</h1><p className="mt-1 text-slate-500">{text}</p></div>{action}</div>; }
function Surface({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <article className={`overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-[0_8px_28px_rgba(15,42,86,.05)] ${className}`}>{children}</article>; }
function Status({ status }: { status: string }) { const style: Record<string, string> = { vencido: "bg-rose-50 text-rose-700", cancelada: "bg-rose-50 text-rose-700", cancelado: "bg-rose-50 text-rose-700", finalizada: "bg-amber-50 text-amber-700", proximo: "bg-blue-50 text-blue-700", adiado: "bg-violet-50 text-violet-700", contatado: "bg-cyan-50 text-cyan-700", concluido: "bg-emerald-50 text-emerald-700", aplicada: "bg-emerald-50 text-emerald-700" }; return <span className={`inline-flex rounded-full px-3 py-1 text-xs font-bold capitalize ${style[status] ?? "bg-slate-100 text-slate-700"}`}>{status.replaceAll("_", " ")}</span>; }

function Patients({ patients, search, setSearch, onNew, onOpen }: { patients: Patient[]; search: string; setSearch: (s: string) => void; onNew: () => void; onOpen: (id: number) => void }) { return <><PageHeading eyebrow="Cadastro e acompanhamento" title="Pacientes" text="Localize cadastros e acompanhe o histórico do paciente." action={<Button onClick={onNew}><UserPlus />Novo paciente</Button>} /><Surface><div className="border-b border-slate-100 p-5"><div className="relative max-w-lg"><Search className="absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><Input value={search} onChange={(e) => setSearch(e.target.value)} className="pl-10" placeholder="Nome, CPF ou telefone" /></div></div>{patients.length ? <div className="divide-y divide-slate-100">{patients.map((p) => <button key={p.id} onClick={() => onOpen(p.id)} className="flex w-full items-center gap-4 px-5 py-4 text-left transition hover:bg-blue-50/40"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-blue-50 text-sm font-bold text-[#0b4ea2]">{initials(p.nome)}</span><div className="min-w-0 flex-1"><strong className="block truncate">{p.nome}</strong><span className="text-sm text-slate-500">Nascimento: {fmtDate(p.nascimento)}</span></div><div className="hidden text-right sm:block"><span className="block text-sm font-medium">{p.telefone}</span><span className="text-xs text-slate-400">{p.cpf ? `CPF ${p.cpf}` : "CPF não informado"}</span></div><ChevronRight className="h-5 w-5 text-slate-400" /></button>)}</div> : <Empty icon={UsersRound} title="Nenhum paciente encontrado" text={search ? "Tente buscar por outro nome, CPF ou telefone." : "Cadastre o primeiro paciente para iniciar o acompanhamento."} action={!search ? <Button onClick={onNew}>Cadastrar paciente</Button> : undefined} />}</Surface></>; }

function PatientDetail({ patient, data, isDoctor, onBack, onRun, saving, onNewRx }: { patient: Patient; data: Payload; isDoctor: boolean; onBack: () => void; onRun: (a: Record<string, unknown>, s: string, c?: () => void) => Promise<void>; saving: boolean; onNewRx: () => void }) {
  const chart = data.charts.find((c) => c.pacienteId === patient.id); const evols = data.evolutions.filter((e) => e.pacienteId === patient.id); const apps = data.applications.filter((a) => a.pacienteId === patient.id); const assessments = data.assessments.filter((a) => a.pacienteId === patient.id);
  const [symptomValues, setSymptomValues] = useState<Record<number, number>>(() => Object.fromEntries(data.symptoms.map((s) => [s.id, 0])));
  const submitChart = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); void onRun({ action: "save_chart", pacienteId: patient.id, anamnese: f.get("anamnese"), alergias: f.get("alergias"), condicoes: f.get("condicoes"), medicamentos: f.get("medicamentos") }, "Prontuário atualizado."); };
  const submitEvolution = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const form = e.currentTarget; const f = new FormData(form); void onRun({ action: "add_evolution", pacienteId: patient.id, texto: f.get("texto") }, "Evolução registrada.").then(() => form.reset()); };
  const saveSymptoms = () => void onRun({ action: "add_symptom_assessment", pacienteId: patient.id, values: data.symptoms.map((s) => ({ sintomaId: s.id, intensidade: symptomValues[s.id] ?? 0 })) }, "Avaliação de sintomas registrada.");
  return <><button onClick={onBack} className="mb-4 text-sm font-semibold text-[#0b62b5]">← Voltar para pacientes</button><PageHeading eyebrow="Prontuário do paciente" title={patient.nome} text={`${fmtDate(patient.nascimento)} • ${patient.telefone}`} action={isDoctor ? <Button onClick={onNewRx}><ClipboardPlus />Nova prescrição</Button> : undefined} />
    <Tabs defaultValue="summary"><TabsList variant="line" className="mb-5 flex max-w-full overflow-x-auto"><TabsTrigger value="summary">Resumo</TabsTrigger>{isDoctor && <><TabsTrigger value="chart">Prontuário</TabsTrigger><TabsTrigger value="symptoms">Sintomas</TabsTrigger><TabsTrigger value="vitamins">Vitaminas</TabsTrigger></>}</TabsList>
      <TabsContent value="summary"><div className="grid gap-5 lg:grid-cols-3"><Surface className="p-5 lg:col-span-2"><h2 className="font-bold">Dados de contato</h2><dl className="mt-4 grid gap-4 sm:grid-cols-2"><Info label="Telefone" value={patient.telefone} /><Info label="CPF" value={patient.cpf || "Não informado"} /><Info label="Endereço" value={patient.endereco || "Não informado"} /><Info label="Contato de emergência" value={patient.contatoEmergencia || "Não informado"} /></dl></Surface><Surface className="p-5"><h2 className="font-bold">Observações administrativas</h2><p className="mt-3 text-sm leading-6 text-slate-600">{patient.observacoesAdmin || "Nenhuma observação registrada."}</p></Surface></div></TabsContent>
      {isDoctor && <TabsContent value="chart"><div className="grid gap-5 xl:grid-cols-[1fr_.8fr]"><Surface className="p-5"><h2 className="mb-5 flex items-center gap-2 font-bold"><Stethoscope className="h-5 w-5 text-[#0b4ea2]" />Dados clínicos essenciais</h2><form onSubmit={submitChart} className="space-y-4"><Field label="Anamnese"><Textarea name="anamnese" defaultValue={chart?.anamnese} rows={4} /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Alergias"><Textarea name="alergias" defaultValue={chart?.alergias} rows={3} /></Field><Field label="Condições clínicas"><Textarea name="condicoes" defaultValue={chart?.condicoes} rows={3} /></Field></div><Field label="Medicamentos em uso"><Textarea name="medicamentos" defaultValue={chart?.medicamentos} rows={3} /></Field><Button disabled={saving}>{saving && <Loader2 className="animate-spin" />}Salvar prontuário</Button></form></Surface><div className="space-y-5"><Surface className="p-5"><h2 className="mb-4 font-bold">Nova evolução</h2><form onSubmit={submitEvolution} className="space-y-3"><Textarea name="texto" required rows={5} placeholder="Registre avaliação, conduta e observações clínicas…" /><Button disabled={saving} className="w-full">Registrar evolução</Button></form></Surface><Surface><div className="border-b border-slate-100 p-5"><h2 className="font-bold">Linha do tempo</h2></div>{evols.length ? <div className="divide-y divide-slate-100">{evols.map((e) => <div key={e.id} className="p-5"><div className="flex items-center justify-between gap-2"><span className="text-xs font-bold uppercase tracking-wide text-[#0b62b5]">{e.tipo}</span><time className="text-xs text-slate-400">{fmtDateTime(e.criadoEm)}</time></div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-700">{e.texto}</p><span className="mt-2 block text-xs text-slate-400">{e.autorNome}</span></div>)}</div> : <Empty icon={History} title="Sem evoluções" text="Os registros clínicos aparecerão em ordem cronológica." />}</Surface></div></div></TabsContent>}
      {isDoctor && <TabsContent value="symptoms"><div className="grid gap-5 xl:grid-cols-[1fr_.9fr]"><Surface className="p-5"><div className="mb-5"><h2 className="font-bold">Nova avaliação</h2><p className="mt-1 text-sm text-slate-500">Marque a intensidade atual de cada sintoma, de 0 a 10.</p></div><div className="space-y-6">{data.symptoms.map((s) => <div key={s.id}><div className="mb-3 flex items-center justify-between"><Label>{s.nome}</Label><strong className="grid h-8 min-w-8 place-items-center rounded-lg bg-blue-50 px-2 text-[#0b4ea2]">{symptomValues[s.id] ?? 0}</strong></div><Slider min={0} max={10} step={1} value={[symptomValues[s.id] ?? 0]} onValueChange={(v) => setSymptomValues((old) => ({ ...old, [s.id]: v[0] }))} /></div>)}</div><Button onClick={saveSymptoms} disabled={saving} className="mt-7">Salvar avaliação</Button></Surface><Surface><div className="border-b border-slate-100 p-5"><h2 className="font-bold">Histórico de sintomas</h2></div>{assessments.length ? <div className="divide-y divide-slate-100">{assessments.slice(0, 12).map((a) => <div key={a.id} className="flex items-center gap-4 p-4"><span className={`grid h-10 w-10 place-items-center rounded-xl font-bold ${a.intensidade >= 7 ? "bg-rose-50 text-rose-700" : a.intensidade >= 4 ? "bg-amber-50 text-amber-700" : "bg-emerald-50 text-emerald-700"}`}>{a.intensidade}</span><div className="flex-1"><strong className="block text-sm">{a.sintomaNome}</strong><span className="text-xs text-slate-400">{fmtDateTime(a.avaliadoEm)}</span></div><div className="h-2 w-24 overflow-hidden rounded-full bg-slate-100"><span className="block h-full rounded-full bg-[#0b74c9]" style={{ width: `${a.intensidade * 10}%` }} /></div></div>)}</div> : <Empty icon={SlidersHorizontal} title="Sem avaliações" text="A primeira avaliação criará a linha de base dos sintomas." />}</Surface></div></TabsContent>}
      {isDoctor && <TabsContent value="vitamins"><Surface><div className="border-b border-slate-100 p-5"><h2 className="font-bold">Histórico de vitaminas</h2><p className="mt-1 text-sm text-slate-500">Prescrições, aplicações e recorrências em uma única linha do tempo.</p></div>{apps.length || data.prescriptions.some((r) => r.pacienteId === patient.id) ? <div className="p-6"><div className="relative space-y-6 before:absolute before:bottom-3 before:left-5 before:top-3 before:w-px before:bg-blue-100">{[...data.prescriptions.filter((r) => r.pacienteId === patient.id).map((r) => ({ date: r.criadoEm, type: "Prescrição", title: r.produtoNome, detail: `${r.dose} • ${r.via}`, status: r.estado })), ...apps.map((a) => ({ date: a.aplicadoEm, type: "Aplicação", title: a.produtoNome, detail: `Lote ${a.loteNumero} • ${a.localAplicacao || "local não informado"}`, status: "aplicada" }))].sort((a, b) => b.date.localeCompare(a.date)).map((event, i) => <div key={`${event.type}-${i}`} className="relative flex gap-4"><span className="z-10 grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#0b4ea2] text-white"><Syringe className="h-4 w-4" /></span><div className="flex-1 rounded-xl border border-slate-100 bg-slate-50/70 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><span className="text-xs font-bold uppercase tracking-wide text-[#0b62b5]">{event.type}</span><h3 className="font-bold">{event.title}</h3></div><Status status={event.status} /></div><p className="mt-2 text-sm text-slate-600">{event.detail}</p><time className="mt-2 block text-xs text-slate-400">{fmtDateTime(event.date)}</time></div></div>)}</div></div> : <Empty icon={Syringe} title="Sem histórico de vitaminas" text="Prescrições e aplicações aparecerão aqui automaticamente." />}</Surface></TabsContent>}
    </Tabs></>;
}

function Info({ label, value }: { label: string; value: string }) { return <div><dt className="text-xs font-semibold uppercase tracking-wide text-slate-400">{label}</dt><dd className="mt-1 text-sm text-slate-700">{value}</dd></div>; }
function Prescriptions({ rows, isDoctor, onNew, onPrint }: { rows: Prescription[]; isDoctor: boolean; onNew: () => void; onPrint: (r: Prescription) => void }) { if (!isDoctor) return <Restricted />; return <><PageHeading eyebrow="Conduta médica" title="Prescrições" text="Documentos finalizados ficam bloqueados e preservam o histórico." action={<Button onClick={onNew}><Plus />Nova prescrição</Button>} /><Surface>{rows.length ? <div className="divide-y divide-slate-100">{rows.map((r) => <div key={r.id} className="flex flex-wrap items-center gap-4 p-5"><span className="grid h-11 w-11 place-items-center rounded-xl bg-blue-50 text-[#0b4ea2]"><FileHeart className="h-5 w-5" /></span><div className="min-w-[180px] flex-1"><strong className="block">{r.pacienteNome}</strong><span className="text-sm text-slate-500">#{String(r.id).padStart(5, "0")} • {fmtDate(r.criadoEm)}</span></div><div className="min-w-[170px]"><span className="block text-xs text-slate-400">Injetável</span><strong className="text-sm">{r.produtoNome}</strong></div><div className="min-w-[130px]"><span className="block text-xs text-slate-400">Dose e via</span><strong className="text-sm">{r.dose} • {r.via}</strong></div><Status status={r.estado} /><Button variant="outline" size="sm" onClick={() => onPrint(r)}><Printer />PDF</Button></div>)}</div> : <Empty icon={FileText} title="Nenhuma prescrição" text="Crie uma prescrição para um paciente cadastrado." action={<Button onClick={onNew}>Criar prescrição</Button>} />}</Surface></>; }
function Applications({ pending, applied, lots, products, isDoctor, onApply }: { pending: Prescription[]; applied: Application[]; lots: Lot[]; products: Product[]; isDoctor: boolean; onApply: (r: Prescription) => void }) { if (!isDoctor) return <Restricted />; return <><PageHeading eyebrow="Confirmação e rastreabilidade" title="Aplicações" text="A baixa do lote acontece somente após a confirmação." /><div className="grid gap-6 xl:grid-cols-2"><Surface><div className="border-b border-slate-100 p-5"><h2 className="font-bold">Aguardando aplicação</h2></div>{pending.length ? <div className="divide-y divide-slate-100">{pending.map((r) => { const validLots = lots.filter((l) => l.produtoId === r.produtoId && l.saldo >= r.quantidade && l.validade >= today()); return <div key={r.id} className="p-5"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-amber-50 text-amber-700"><Syringe className="h-5 w-5" /></span><div className="flex-1"><strong className="block">{r.pacienteNome}</strong><span className="text-sm text-slate-500">{r.produtoNome} • {r.dose}</span></div><Status status={r.estado} /></div><div className="mt-4 flex items-center justify-between rounded-xl bg-slate-50 p-3"><span className="text-xs text-slate-500">{validLots.length ? `${validLots.length} lote(s) válido(s)` : "Sem lote válido com saldo"}</span><Button size="sm" disabled={!validLots.length} onClick={() => onApply(r)}>Confirmar aplicação</Button></div></div>; })}</div> : <Empty icon={Check} title="Tudo em dia" text="Não há prescrições aguardando aplicação." />}</Surface><Surface><div className="border-b border-slate-100 p-5"><h2 className="font-bold">Aplicações recentes</h2></div>{applied.length ? <div className="divide-y divide-slate-100">{applied.slice(0, 10).map((a) => <div key={a.id} className="flex items-center gap-3 p-5"><span className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-emerald-700"><Check className="h-5 w-5" /></span><div className="flex-1"><strong className="block">{a.pacienteNome}</strong><span className="text-sm text-slate-500">{a.produtoNome} • lote {a.loteNumero}</span></div><time className="text-xs text-slate-400">{fmtDateTime(a.aplicadoEm)}</time></div>)}</div> : <Empty icon={History} title="Sem aplicações" text="As aplicações confirmadas aparecerão com lote e horário." />}</Surface></div></>; }
function Stock({ products, lots, onReceive }: { products: (Product & { balance: number })[]; lots: Lot[]; onReceive: () => void }) { return <><PageHeading eyebrow="Lotes, validade e saldo" title="Estoque de injetáveis" text="O sistema prioriza o lote válido com vencimento mais próximo." action={<Button onClick={onReceive}><PackagePlus />Registrar entrada</Button>} /><div className="grid gap-4 md:grid-cols-2">{products.map((p) => <Surface key={p.id} className="p-5"><div className="flex items-start justify-between gap-4"><div><span className="text-xs font-semibold uppercase tracking-wide text-[#0b74c9]">{p.principioAtivo}</span><h2 className="mt-1 text-lg font-bold">{p.nome}</h2><p className="text-sm text-slate-500">{p.apresentacao}</p></div><span className={`grid h-12 min-w-16 place-items-center rounded-xl px-3 text-xl font-bold ${p.balance <= p.estoqueMinimo ? "bg-rose-50 text-rose-700" : "bg-emerald-50 text-emerald-700"}`}>{p.balance}</span></div><div className="mt-5 border-t border-slate-100 pt-4"><div className="mb-2 flex justify-between text-xs text-slate-400"><span>Lotes ativos</span><span>Mínimo: {p.estoqueMinimo} {p.unidade}s</span></div><div className="space-y-2">{lots.filter((l) => l.produtoId === p.id && l.saldo > 0).map((l) => <div key={l.id} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-sm"><span>Lote <strong>{l.numero}</strong></span><span className={l.validade < today() ? "font-semibold text-rose-600" : "text-slate-500"}>{l.saldo} • {fmtDate(l.validade)}</span></div>)}{!lots.some((l) => l.produtoId === p.id && l.saldo > 0) && <p className="py-2 text-sm text-slate-400">Nenhum lote com saldo.</p>}</div></div></Surface>)}</div></>; }
function Reminders({ rows, onRun, saving }: { rows: Reminder[]; onRun: (a: Record<string, unknown>, s: string, c?: () => void) => Promise<void>; saving: boolean }) { return <><PageHeading eyebrow="Acompanhamento ativo" title="Recorrências" text="Organize os contatos sem expor informações clínicas à recepção." /><Surface>{rows.length ? <div className="divide-y divide-slate-100">{rows.map((r) => <div key={r.id} className="flex flex-wrap items-center gap-4 p-5"><span className="grid h-11 w-11 place-items-center rounded-xl bg-blue-50 text-sm font-bold text-[#0b4ea2]">{initials(r.pacienteNome)}</span><div className="min-w-[180px] flex-1"><strong className="block">{r.pacienteNome}</strong><span className="text-sm text-slate-500">{r.telefone}</span></div><div className="min-w-[150px]"><span className="block text-xs text-slate-400">Retorno</span><strong className="text-sm">{r.produtoNome ?? "Acompanhamento"}</strong></div><div className="min-w-[110px]"><span className="block text-xs text-slate-400">Data prevista</span><strong className="text-sm">{fmtDate(r.dataPrevista)}</strong></div><Status status={r.dataPrevista < today() && r.estado === "proximo" ? "vencido" : r.estado} /><div className="flex gap-2"><Button variant="outline" size="sm" disabled={saving || r.estado === "contatado"} onClick={() => void onRun({ action: "update_reminder", id: r.id, estado: "contatado", notaAdministrativa: "Contato registrado pela equipe." }, "Contato registrado.")}>Contatado</Button><Button size="sm" disabled={saving || r.estado === "concluido"} onClick={() => void onRun({ action: "update_reminder", id: r.id, estado: "concluido", notaAdministrativa: r.notaAdministrativa }, "Recorrência concluída.")}>Concluir</Button></div></div>)}</div> : <Empty icon={CalendarClock} title="Sem recorrências" text="Ao confirmar uma aplicação recorrente, o próximo contato será criado automaticamente." />}</Surface></>; }
function Admin({ data, isDoctor, onRun, saving }: { data: Payload; isDoctor: boolean; onRun: (a: Record<string, unknown>, s: string, c?: () => void) => Promise<void>; saving: boolean }) {
  if (!isDoctor) return <Restricted />;
  const addSymptom = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const form = e.currentTarget; const f = new FormData(form); void onRun({ action: "add_symptom", nome: f.get("nome") }, "Sintoma adicionado.").then(() => form.reset()); };
  return <><PageHeading eyebrow="Configurações e rastreabilidade" title="Administração" text="Gerencie perfis, catálogos e consulte as ações registradas." /><Tabs defaultValue="users"><TabsList variant="line" className="mb-5"><TabsTrigger value="users">Usuários</TabsTrigger><TabsTrigger value="catalogs">Catálogos</TabsTrigger><TabsTrigger value="audit">Auditoria</TabsTrigger></TabsList>
    <TabsContent value="users"><Surface>{data.users.map((u) => <div key={u.id} className="flex flex-wrap items-center gap-4 border-b border-slate-100 p-5 last:border-0"><span className="grid h-10 w-10 place-items-center rounded-xl bg-blue-50 text-sm font-bold text-[#0b4ea2]">{initials(u.nome)}</span><div className="min-w-[180px] flex-1"><strong className="block">{u.nome}</strong><span className="text-sm text-slate-500">{u.email}</span></div><Select value={u.papel} disabled={saving || u.id === data.user.id} onValueChange={(papel) => void onRun({ action: "update_user_role", id: u.id, papel }, "Perfil atualizado.")}><SelectTrigger className="w-52"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="medico_admin">Médico administrador</SelectItem><SelectItem value="recepcao">Recepção</SelectItem></SelectContent></Select></div>)}</Surface></TabsContent>
    <TabsContent value="catalogs"><div className="grid gap-5 lg:grid-cols-2"><Surface className="p-5"><h2 className="font-bold">Sintomas monitorados</h2><div className="mt-4 flex flex-wrap gap-2">{data.symptoms.map((s) => <span key={s.id} className="rounded-full bg-blue-50 px-3 py-1.5 text-sm font-medium text-[#0b4ea2]">{s.nome}</span>)}</div><form onSubmit={addSymptom} className="mt-5 flex gap-2"><Input name="nome" required placeholder="Novo sintoma" /><Button disabled={saving}><Plus />Adicionar</Button></form></Surface><Surface className="p-5"><h2 className="font-bold">Estoque mínimo por produto</h2><div className="mt-4 space-y-4">{data.products.map((p) => <form key={p.id} onSubmit={(e) => { e.preventDefault(); const f = new FormData(e.currentTarget); void onRun({ action: "update_product_minimum", id: p.id, estoqueMinimo: Number(f.get("estoqueMinimo")) }, "Estoque mínimo atualizado."); }} className="flex items-center gap-3"><div className="flex-1"><strong className="block text-sm">{p.nome}</strong><span className="text-xs text-slate-400">{p.apresentacao}</span></div><Input className="w-24" name="estoqueMinimo" type="number" min="0" step="1" defaultValue={p.estoqueMinimo} /><Button size="sm" variant="outline">Salvar</Button></form>)}</div></Surface></div></TabsContent>
    <TabsContent value="audit"><Surface>{data.audit.length ? <div className="divide-y divide-slate-100">{data.audit.map((a) => <div key={a.id} className="grid gap-2 p-4 text-sm sm:grid-cols-[160px_1fr_1fr]"><time className="text-slate-400">{fmtDateTime(a.criadoEm)}</time><span><strong>{a.usuarioNome || "Sistema"}</strong> {a.acao.replaceAll("_", " ")}</span><span className="text-slate-500">{a.entidade}{a.entidadeId ? ` #${a.entidadeId}` : ""}</span></div>)}</div> : <Empty icon={History} title="Auditoria vazia" text="As ações dos usuários aparecerão aqui." />}</Surface></TabsContent>
  </Tabs></>;
}
function Restricted() { return <Surface><Empty icon={ShieldCheck} title="Conteúdo clínico protegido" text="Este perfil possui acesso administrativo. Prescrições e dados clínicos são restritos ao médico responsável." /></Surface>; }

function PatientDialog({ open, setOpen, run, saving }: { open: boolean; setOpen: (o: boolean) => void; run: (a: Record<string, unknown>, s: string, c?: () => void) => Promise<void>; saving: boolean }) { const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); void run({ action: "create_patient", nome: f.get("nome"), nascimento: f.get("nascimento"), cpf: f.get("cpf"), telefone: f.get("telefone"), endereco: f.get("endereco"), contatoEmergencia: f.get("contatoEmergencia"), observacoesAdmin: f.get("observacoesAdmin") }, "Paciente cadastrado.", () => setOpen(false)); }; return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>Novo paciente</DialogTitle><DialogDescription>Cadastre os dados administrativos essenciais. O prontuário clínico será preenchido pelo médico.</DialogDescription></DialogHeader><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2"><Field label="Nome completo"><Input name="nome" required autoFocus /></Field><Field label="Data de nascimento"><Input name="nascimento" type="date" required /></Field><Field label="CPF (opcional)"><Input name="cpf" inputMode="numeric" placeholder="000.000.000-00" /></Field><Field label="Telefone"><Input name="telefone" required placeholder="(85) 99999-9999" /></Field><Field label="Endereço"><Input name="endereco" /></Field><Field label="Contato de emergência"><Input name="contatoEmergencia" /></Field><div className="sm:col-span-2"><Field label="Observações administrativas"><Textarea name="observacoesAdmin" rows={3} /></Field></div><DialogFooter className="sm:col-span-2"><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving}>{saving && <Loader2 className="animate-spin" />}Salvar paciente</Button></DialogFooter></form></DialogContent></Dialog>; }
function StockDialog({ open, setOpen, products, run, saving }: { open: boolean; setOpen: (o: boolean) => void; products: Product[]; run: (a: Record<string, unknown>, s: string, c?: () => void) => Promise<void>; saving: boolean }) { const [productId, setProductId] = useState(""); const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); void run({ action: "receive_stock", produtoId: Number(productId), numero: f.get("numero"), validade: f.get("validade"), quantidade: Number(f.get("quantidade")) }, "Entrada registrada.", () => setOpen(false)); }; return <Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Entrada de estoque</DialogTitle><DialogDescription>Informe lote e validade para manter a rastreabilidade do injetável.</DialogDescription></DialogHeader><form onSubmit={submit} className="space-y-4"><Field label="Produto"><Select value={productId} onValueChange={setProductId}><SelectTrigger className="w-full"><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{products.map((p) => <SelectItem key={p.id} value={String(p.id)}>{p.nome} — {p.apresentacao}</SelectItem>)}</SelectContent></Select></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Número do lote"><Input name="numero" required /></Field><Field label="Validade"><Input name="validade" type="date" required /></Field></div><Field label="Quantidade recebida"><Input name="quantidade" type="number" min="0.01" step="0.01" required /></Field><DialogFooter><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving || !productId}>Registrar entrada</Button></DialogFooter></form></DialogContent></Dialog>; }
function PrescriptionDialog({ open, setOpen, patients, products, run, saving }: { open: boolean; setOpen: (o: boolean) => void; patients: Patient[]; products: Product[]; run: (a: Record<string, unknown>, s: string, c?: () => void) => Promise<void>; saving: boolean }) { const [patientId, setPatientId] = useState(""); const [productId, setProductId] = useState(""); const [via, setVia] = useState("IM"); const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); void run({ action: "create_prescription", pacienteId: Number(patientId), produtoId: Number(productId), dose: f.get("dose"), via, quantidade: Number(f.get("quantidade")), instrucoes: f.get("instrucoes"), recorrenciaDias: Number(f.get("recorrenciaDias")), observacoes: f.get("observacoes") }, "Prescrição finalizada.", () => setOpen(false)); }; return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>Nova prescrição</DialogTitle><DialogDescription>Ao salvar, a prescrição será finalizada e ficará bloqueada para alterações.</DialogDescription></DialogHeader><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2"><Field label="Paciente"><Select value={patientId} onValueChange={setPatientId}><SelectTrigger className="w-full"><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{patients.map((p) => <SelectItem key={p.id} value={String(p.id)}>{p.nome}</SelectItem>)}</SelectContent></Select></Field><Field label="Injetável"><Select value={productId} onValueChange={setProductId}><SelectTrigger className="w-full"><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{products.map((p) => <SelectItem key={p.id} value={String(p.id)}>{p.nome}</SelectItem>)}</SelectContent></Select></Field><Field label="Dose"><Input name="dose" required placeholder="Ex.: 1 mL" /></Field><Field label="Via"><Select value={via} onValueChange={setVia}><SelectTrigger className="w-full"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="IM">Intramuscular (IM)</SelectItem><SelectItem value="IV">Intravenosa (IV)</SelectItem><SelectItem value="SC">Subcutânea (SC)</SelectItem></SelectContent></Select></Field><Field label="Quantidade a consumir"><Input name="quantidade" type="number" min="0.01" step="0.01" defaultValue="1" required /></Field><Field label="Recorrência em dias (opcional)"><Input name="recorrenciaDias" type="number" min="1" placeholder="Ex.: 90" /></Field><div className="sm:col-span-2"><Field label="Instruções"><Textarea name="instrucoes" rows={3} placeholder="Orientações para a aplicação" /></Field></div><div className="sm:col-span-2"><Field label="Observações"><Textarea name="observacoes" rows={2} /></Field></div><DialogFooter className="sm:col-span-2"><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving || !patientId || !productId}>Finalizar prescrição</Button></DialogFooter></form></DialogContent></Dialog>; }
function ApplicationDialog({ rx, setRx, lots, run, saving }: { rx: Prescription | null; setRx: (r: Prescription | null) => void; lots: Lot[]; run: (a: Record<string, unknown>, s: string, c?: () => void) => Promise<void>; saving: boolean }) { const valid = useMemo(() => rx ? lots.filter((l) => l.produtoId === rx.produtoId && l.saldo >= rx.quantidade && l.validade >= today()).sort((a, b) => a.validade.localeCompare(b.validade)) : [], [rx, lots]); const [lotId, setLotId] = useState(""); useEffect(() => { setLotId(valid[0] ? String(valid[0].id) : ""); }, [rx, valid.length]); const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); if (!rx) return; const f = new FormData(e.currentTarget); void run({ action: "apply_prescription", prescricaoId: rx.id, loteId: Number(lotId), localAplicacao: f.get("localAplicacao"), observacoes: f.get("observacoes"), reacao: f.get("reacao") }, "Aplicação confirmada e estoque atualizado.", () => setRx(null)); }; return <Dialog open={!!rx} onOpenChange={(o) => !o && setRx(null)}><DialogContent><DialogHeader><DialogTitle>Confirmar aplicação</DialogTitle><DialogDescription>{rx ? `${rx.pacienteNome} • ${rx.produtoNome} • ${rx.dose}` : ""}</DialogDescription></DialogHeader><form onSubmit={submit} className="space-y-4"><Field label="Lote — sugestão FEFO"><Select value={lotId} onValueChange={setLotId}><SelectTrigger className="w-full"><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{valid.map((l, index) => <SelectItem key={l.id} value={String(l.id)}>{index === 0 ? "Recomendado • " : ""}Lote {l.numero} • vence {fmtDate(l.validade)} • saldo {l.saldo}</SelectItem>)}</SelectContent></Select></Field><Field label="Local da aplicação"><Input name="localAplicacao" required placeholder="Ex.: deltoide direito" /></Field><Field label="Observações"><Textarea name="observacoes" rows={2} /></Field><Field label="Reação observada"><Textarea name="reacao" rows={2} placeholder="Nenhuma ou descreva a reação" /></Field><DialogFooter><Button type="button" variant="outline" onClick={() => setRx(null)}>Cancelar</Button><Button disabled={saving || !lotId}><Syringe />Confirmar e baixar estoque</Button></DialogFooter></form></DialogContent></Dialog>; }
function PrescriptionPrint({ rx, onClose }: { rx: Prescription; onClose: () => void }) { return <div className="print-sheet hidden bg-white p-12 text-[#10203b] print:block"><div className="flex items-center gap-5 border-b-2 border-[#0b4ea2] pb-6"><img src="/logo.jpg" alt="CTI" className="h-20 w-20 object-contain" /><div><h1 className="text-2xl font-bold text-[#082c68]">CTI — Centro de Terapias Integradas</h1><p className="mt-1 text-sm">Prescrição médica para aplicação presencial</p></div></div><div className="mt-8 grid grid-cols-2 gap-5 text-sm"><Info label="Paciente" value={rx.pacienteNome} /><Info label="Data de emissão" value={fmtDate(rx.finalizadoEm || rx.criadoEm)} /><Info label="Médico" value={rx.medicoNome} /><Info label="Número" value={`#${String(rx.id).padStart(5, "0")}`} /></div><div className="mt-10 rounded-xl border-2 border-slate-200 p-6"><h2 className="text-xl font-bold">{rx.produtoNome}</h2><p className="mt-1 text-slate-600">{rx.apresentacao}</p><div className="mt-5 grid grid-cols-3 gap-4"><Info label="Dose" value={rx.dose} /><Info label="Via" value={rx.via} /><Info label="Quantidade" value={String(rx.quantidade)} /></div>{rx.instrucoes && <div className="mt-5"><Info label="Instruções" value={rx.instrucoes} /></div>}</div>{rx.observacoes && <div className="mt-6"><Info label="Observações" value={rx.observacoes} /></div>}<div className="mt-28 text-center"><div className="mx-auto w-80 border-t border-slate-500 pt-2 text-sm">{rx.medicoNome}<br />CRM configurado no cadastro profissional</div></div><p className="mt-20 border-t border-slate-200 pt-4 text-xs text-slate-500">Documento destinado à impressão e assinatura manual. Não possui assinatura digital.</p><button className="print:hidden" onClick={onClose}>Fechar</button></div>; }
